import (
	"encoding/json"
	"os"
)

type input struct {
	Method string
	Path string
	Host string
	HeaderCount int
	BodyBytes int
}

func main() {
 var cases []input
 if err:=json.Unmarshal([]byte(os.Args[1]), &cases); err!=nil { panic(err) }
 enc:=json.NewEncoder(os.Stdout)
 for _, in:=range cases {
  var out any
  out = RequestSummary(in.Method,in.Path,in.Host,in.HeaderCount,in.BodyBytes)
  if err:=enc.Encode(out); err!=nil { panic(err) }
 }
}
